// ============================================
// GOOGLE APPS SCRIPT - BACKEND (Code.gs)
// ============================================

// Configuration for Sheet IDs and Names
const CONFIG = {
  EWC_AR_OUTSTANDING: {
    sheetId: '19E9HQBf4zHn7mrnX6Rp2fen3Da_VJ1Ex6-5nC9uWsFo',
    sheetName: 'Current Sheet',
    range: 'A:Y'
  },
  AR_OUTSTANDING: {
    sheetId: '1DFFkBfPAwtq-n4LWD96SYbQUCIDM2TZsIp0cpcLKZjg',
    sheets: {
      dropdown: { name: 'AR oustanding Dropdown', range: 'A:G' },
      payerInfo: { name: 'Payer Info', range: 'A:F' },
      patientMaster: { name: 'Patient Master Sheet', range: 'A:L' },
      credentialing: { name: 'Credentialing Info', range: 'A:E' }
    }
  },
  LAH_CONSOLIDATED: {
    sheetId: '1S8gn2ThGW5F5nQS1G_XSaSuLPJmJLw5A-qQUcHp-pqg',
    sheetName: 'Current Sheet',
    range: 'A:I',
    enabled: true  // Set to false to disable Tracker Log
  }
};

// Column mappings for EWC AR Outstanding (Current Sheet)
const COLUMNS = {
  CLIENT: 0,
  STATE: 1,
  VISIT_ID: 2,
  PATIENT_NAME: 3,
  DOS: 4,
  AGING_DAYS: 5,
  AGING_BUCKET: 6,
  SUBMITTED_DATE: 7,
  INSURANCE_NAME: 8,
  STATUS: 9,
  BILLED_AMOUNT: 10,
  BALANCE_AMOUNT: 11,
  TYPE: 12,
  AR_NOTES: 13,
  TYPE_FIELD: 14,
  STATUS_CODE: 15,
  ACTION_CODE: 16,
  ASSIGNED_TO: 17,
  WORKED_BY: 18,
  WORKED_DATE: 19,
  FOLLOWUP_DATE: 20,
  CLAIM_TYPE: 21,
  ALLOCATED_USER: 22,
  ALLOCATION_DATE: 23,
  REMARKS: 24
};

// ============================================
// MAIN FUNCTIONS
// ============================================

function doGet() {
  return HtmlService.createHtmlOutputFromFile('Index')
    .setTitle('AR Worklist')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

// ============================================
// DATA RETRIEVAL FUNCTIONS
// ============================================

function getAllAccountsData() {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.EWC_AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.EWC_AR_OUTSTANDING.sheetName);

    const data = sheet.getDataRange().getValues();
    const rows = data.slice(1); // Skip header row

    return rows.map(row => ({
      client: row[COLUMNS.CLIENT],
      state: row[COLUMNS.STATE],
      visitId: row[COLUMNS.VISIT_ID],
      patientName: row[COLUMNS.PATIENT_NAME],
      dos: formatDate(row[COLUMNS.DOS]),
      agingDays: row[COLUMNS.AGING_DAYS],
      agingBucket: row[COLUMNS.AGING_BUCKET],
      submittedDate: formatDate(row[COLUMNS.SUBMITTED_DATE]),
      insurance: row[COLUMNS.INSURANCE_NAME],
      status: row[COLUMNS.STATUS],
      billedAmount: row[COLUMNS.BILLED_AMOUNT],
      balanceAmount: row[COLUMNS.BALANCE_AMOUNT],
      type: row[COLUMNS.TYPE],
      arNotes: row[COLUMNS.AR_NOTES],
      statusCode: row[COLUMNS.STATUS_CODE],
      actionCode: row[COLUMNS.ACTION_CODE],
      assignedTo: row[COLUMNS.ASSIGNED_TO],
      workedBy: row[COLUMNS.WORKED_BY],
      workedDate: formatDate(row[COLUMNS.WORKED_DATE]),
      followupDate: formatDate(row[COLUMNS.FOLLOWUP_DATE]),
      claimType: row[COLUMNS.CLAIM_TYPE],
      allocatedUser: row[COLUMNS.ALLOCATED_USER],
      allocationDate: formatDate(row[COLUMNS.ALLOCATION_DATE]),
      remarks: row[COLUMNS.REMARKS]
    }));
  } catch (error) {
    throw new Error('Error fetching accounts data: ' + error.message);
  }
}

function getAccountByVisitId(visitId) {
  try {
    const allData = getAllAccountsData();
    return allData.find(account => String(account.visitId).trim() === String(visitId).trim()) || null;
  } catch (error) {
    throw new Error('Error fetching account by Visit ID: ' + error.message);
  }
}

function getDropdownOptions() {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.AR_OUTSTANDING.sheets.dropdown.name);

    const data = sheet.getDataRange().getValues();
    const rows = data.slice(1);

    return {
      source: [...new Set(rows.map(r => r[0]).filter(v => v))],
      statusCode: [...new Set(rows.map(r => r[1]).filter(v => v))],
      actionCode: [...new Set(rows.map(r => r[2]).filter(v => v))],
      assignedTo: [...new Set(rows.map(r => r[3]).filter(v => v))],
      claimType: [...new Set(rows.map(r => r[4]).filter(v => v))],
      client: [...new Set(rows.map(r => r[5]).filter(v => v))],
      users: [...new Set(rows.map(r => r[6]).filter(v => v))]
    };
  } catch (error) {
    throw new Error('Error fetching dropdown options: ' + error.message);
  }
}

function getPatientInfo(visitId) {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.AR_OUTSTANDING.sheets.patientMaster.name);

    if (!sheet) {
      Logger.log('Patient Master Sheet not found');
      return null;
    }

    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const rows = data.slice(1);

    Logger.log('Patient Master Sheet columns: ' + headers.join(', '));

    // Your Patient Master Sheet structure:
    // A: S. No
    // B: Patient ID# (e.g., PT13214234)
    // C: Patient Name (e.g., Smith, Emily)
    // D: DOB (e.g., 12/08/1998)
    // E: Primary Insurance Name (e.g., Medicare)
    // F: Primary Insurance ID (e.g., 12KH35HL5W10)
    // G: Secondary Insurance Name (e.g., Humana)
    // H: Secondary Insurance ID (e.g., 97232423D214)
    // I: IPA Details
    // J: Effective Date
    // K: Remarks
    // L: Billing Comment

    let patientRow = null;

    // Try to find by Patient ID (Column B)
    for (let i = 0; i < rows.length; i++) {
      const patientId = String(rows[i][1]).trim();
      if (patientId === visitId) {
        patientRow = rows[i];
        break;
      }
    }

    // If not found, use first patient as fallback (for demo purposes)
    if (!patientRow && rows.length > 0) {
      Logger.log('Patient not found by Visit ID, using first patient');
      patientRow = rows[0];
    }

    if (!patientRow) {
      Logger.log('No patient data available');
      return null;
    }

    return {
      patientId: patientRow[1],              // Column B - Patient ID#
      patientName: patientRow[2],            // Column C - Patient Name
      dob: formatDate(patientRow[3]),        // Column D - DOB
      primaryInsurance: patientRow[4],       // Column E - Primary Insurance Name
      primaryInsuranceId: patientRow[5],     // Column F - Primary Insurance ID
      secondaryInsurance: patientRow[6],     // Column G - Secondary Insurance Name
      secondaryInsuranceId: patientRow[7],   // Column H - Secondary Insurance ID
      ipaDetails: patientRow[8],             // Column I - IPA Details
      effectiveDate: formatDate(patientRow[9]), // Column J - Effective Date
      remarks: patientRow[10],               // Column K - Remarks
      billingComment: patientRow[11]         // Column L - Billing Comment
    };
  } catch (error) {
    Logger.log('Error fetching patient info: ' + error.message);
    return null;
  }
}

function getPayerInfo(client) {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.AR_OUTSTANDING.sheets.payerInfo.name);

    const data = sheet.getDataRange().getValues();
    const rows = data.slice(1);

    const payerRow = rows.find(row => row[0] === client);

    if (!payerRow) return null;

    return {
      client: payerRow[0],
      name: payerRow[1],
      npi: payerRow[2],
      tax: payerRow[3],
      ptan: payerRow[4],
      address: payerRow[5]
    };
  } catch (error) {
    Logger.log('Error fetching payer info: ' + error.message);
    return null;
  }
}

function getCredentialingInfo(client) {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.AR_OUTSTANDING.sheets.credentialing.name);

    const data = sheet.getDataRange().getValues();
    const rows = data.slice(1);

    const credRow = rows.find(row => row[0] === client);

    if (!credRow) return null;

    return {
      client: credRow[0],
      payer: credRow[1],
      credentialingStatus: credRow[2],
      w9Status: credRow[3],
      w9UpdatedDate: formatDate(credRow[4])
    };
  } catch (error) {
    Logger.log('Error fetching credentialing info: ' + error.message);
    return null;
  }
}

function getClaimHistory(visitId) {
  // Skip if tracker log is disabled
  if (!CONFIG.LAH_CONSOLIDATED.enabled) {
    Logger.log('Tracker Log is disabled - returning empty history');
    return [];
  }

  try {
    const sheet = SpreadsheetApp.openById(CONFIG.LAH_CONSOLIDATED.sheetId)
      .getSheetByName(CONFIG.LAH_CONSOLIDATED.sheetName);

    if (!sheet) {
      Logger.log('Tracker Log sheet not found - returning empty history');
      return [];
    }

    const data = sheet.getDataRange().getValues();
    const rows = data.slice(1); // Skip header row

    Logger.log('Total rows in Tracker Log: ' + rows.length);
    Logger.log('Looking for Visit ID: ' + visitId);

    // Filter by Visit ID (Column B) with trim
    const allHistory = rows
      .filter(row => {
        const rowVisitId = String(row[1]).trim();
        const searchVisitId = String(visitId).trim();
        return rowVisitId === searchVisitId;
      })
      .map(row => ({
        timestamp: row[0],       // Column A - Timestamp
        visitId: row[1],         // Column B - Visit ID
        client: row[2],          // Column C - Client
        statusCode: row[3],      // Column D - Status Code
        actionCode: row[4],      // Column E - Action Code
        assignedTo: row[5],      // Column F - Assigned To
        arComments: row[6],      // Column G - AR comment
        workedBy: row[7],        // Column H - Worked By
        workedDate: row[8],      // Column I - Worked Date
        rawTimestamp: row[0]
      }));

    Logger.log('Found ' + allHistory.length + ' matching entries');

    if (allHistory.length === 0) {
      return [];
    }

    // Sort by timestamp ASCENDING (oldest first)
    allHistory.sort((a, b) => {
      const dateA = new Date(a.rawTimestamp);
      const dateB = new Date(b.rawTimestamp);
      return dateA - dateB;
    });

    // Take last 5 entries (most recent)
    const last5 = allHistory.slice(-5);

    Logger.log('Returning last 5 entries');

    // Format and return
    return last5.map(item => ({
      timestamp: formatDate(item.timestamp),
      visitId: item.visitId,
      client: item.client,
      statusCode: item.statusCode,
      actionCode: item.actionCode,
      assignedTo: item.assignedTo,
      arComments: item.arComments,
      workedBy: item.workedBy,
      workedDate: formatDate(item.workedDate)
    }));

  } catch (error) {
    Logger.log('Error fetching claim history: ' + error.message);
    Logger.log('Full error: ' + error.toString());
    return [];
  }
}

// ============================================
// DATA UPDATE FUNCTIONS
// ============================================

function updateAccountWorkForm(visitId, formData) {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.EWC_AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.EWC_AR_OUTSTANDING.sheetName);

    const data = sheet.getDataRange().getValues();

    // Find row with matching Visit ID
    let rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][COLUMNS.VISIT_ID]).trim() === String(visitId).trim()) {
        rowIndex = i + 1; // Sheet rows are 1-indexed
        break;
      }
    }

    if (rowIndex === -1) {
      throw new Error('Visit ID not found: ' + visitId);
    }

    // Update fields
    if (formData.notes !== undefined && formData.notes !== null) {
      sheet.getRange(rowIndex, COLUMNS.AR_NOTES + 1).setValue(formData.notes);
    }
    if (formData.source) {
      sheet.getRange(rowIndex, COLUMNS.TYPE_FIELD + 1).setValue(formData.source);
    }
    if (formData.statusCode) {
      sheet.getRange(rowIndex, COLUMNS.STATUS_CODE + 1).setValue(formData.statusCode);
    }
    if (formData.actionCode) {
      sheet.getRange(rowIndex, COLUMNS.ACTION_CODE + 1).setValue(formData.actionCode);
    }
    if (formData.assignedTo) {
      sheet.getRange(rowIndex, COLUMNS.ASSIGNED_TO + 1).setValue(formData.assignedTo);
    }
    if (formData.followupDate) {
      sheet.getRange(rowIndex, COLUMNS.FOLLOWUP_DATE + 1).setValue(new Date(formData.followupDate));
    }

    // Auto-update Worked By and Worked Date
    const currentUser = Session.getActiveUser().getEmail();
    sheet.getRange(rowIndex, COLUMNS.WORKED_BY + 1).setValue(currentUser);
    sheet.getRange(rowIndex, COLUMNS.WORKED_DATE + 1).setValue(new Date());

    // Force save
    SpreadsheetApp.flush();

    // Log to Tracker Log if enabled
    if (CONFIG.LAH_CONSOLIDATED && CONFIG.LAH_CONSOLIDATED.enabled === true) {
      try {
        logToTrackerLog(visitId, formData);
      } catch (logError) {
        Logger.log('Warning: Could not log to tracker: ' + logError.message);
      }
    } else {
      Logger.log('Tracker Log is disabled - skipping');
    }

    return { success: true, message: 'Account updated successfully' };
  } catch (error) {
    Logger.log('Error in updateAccountWorkForm: ' + error.toString());
    throw new Error('Error updating account: ' + error.message);
  }
}

function logToTrackerLog(visitId, formData) {
  if (!CONFIG.LAH_CONSOLIDATED.enabled) {
    Logger.log('Tracker Log disabled - skipping');
    return;
  }

  try {
    const ss = SpreadsheetApp.openById(CONFIG.LAH_CONSOLIDATED.sheetId);
    const sheet = ss.getSheetByName(CONFIG.LAH_CONSOLIDATED.sheetName);

    if (!sheet) {
      throw new Error('Tracker Log sheet not found: ' + CONFIG.LAH_CONSOLIDATED.sheetName);
    }

    const account = getAccountByVisitId(visitId);

    if (!account) {
      throw new Error('Account not found for Visit ID: ' + visitId);
    }

    const currentUser = Session.getActiveUser().getEmail();
    const now = new Date();

    // Append row matching your Tracker Log structure (A-I)
    sheet.appendRow([
      now,                        // A - Timestamp
      visitId,                    // B - Visit ID
      account.client || '',       // C - Client
      formData.statusCode || '',  // D - Status Code
      formData.actionCode || '',  // E - Action Code
      formData.assignedTo || '',  // F - Assigned To
      formData.notes || '',       // G - AR comment
      currentUser,                // H - Worked By
      now                         // I - Worked Date
    ]);

    SpreadsheetApp.flush();
    Logger.log('Successfully logged to Tracker Log for Visit ID: ' + visitId);

  } catch (error) {
    Logger.log('Tracker Log Error: ' + error.toString());
    Logger.log('Note: Main update succeeded. Tracker Log is optional.');
  }
}

function updateRemarks(visitId, remarks) {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.EWC_AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.EWC_AR_OUTSTANDING.sheetName);

    const data = sheet.getDataRange().getValues();

    for (let i = 1; i < data.length; i++) {
      if (String(data[i][COLUMNS.VISIT_ID]).trim() === String(visitId).trim()) {
        sheet.getRange(i + 1, COLUMNS.REMARKS + 1).setValue(remarks);
        SpreadsheetApp.flush();
        return { success: true, message: 'Remarks updated successfully' };
      }
    }

    throw new Error('Visit ID not found: ' + visitId);
  } catch (error) {
    Logger.log('Error updating remarks: ' + error.toString());
    throw new Error('Error updating remarks: ' + error.message);
  }
}

// ============================================
// STATISTICS FUNCTIONS
// ============================================

function getAccountStatistics() {
  try {
    const allData = getAllAccountsData();
    const currentUserName = getCurrentUserDisplayName();

    // Filter by Allocated User column (W)
    const assigned = allData.filter(a => 
      a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase())
    ).length;

    const worked = allData.filter(a => 
      a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
      a.workedBy && a.workedDate
    ).length;

    const pending = allData.filter(a => 
      a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
      a.statusCode === 'Pending'
    ).length;

    const nonWorkable = allData.filter(a => 
      a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
      a.statusCode === 'Non-Workable'
    ).length;

    return {
      totalAssigned: assigned,
      totalWorked: worked,
      totalPending: pending,
      totalNonWorkable: nonWorkable
    };
  } catch (error) {
    throw new Error('Error fetching statistics: ' + error.message);
  }
}

function getAssignedAccounts() {
  try {
    const allData = getAllAccountsData();
    const currentUserName = getCurrentUserDisplayName();

    // Filter by Allocated User column
    return allData.filter(a => 
      a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase())
    );
  } catch (error) {
    throw new Error('Error fetching assigned accounts: ' + error.message);
  }
}

// ============================================
// EXPORT FUNCTIONS
// ============================================

function exportAccountsToCSV(accountType) {
  try {
    const allData = getAllAccountsData();
    const currentUserName = getCurrentUserDisplayName();

    let filteredData = [];

    switch(accountType) {
      case 'assigned':
        filteredData = allData.filter(a => 
          a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase())
        );
        break;
      case 'worked':
        filteredData = allData.filter(a => 
          a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
          a.workedBy && a.workedDate
        );
        break;
      case 'pending':
        filteredData = allData.filter(a => 
          a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
          a.statusCode === 'Pending'
        );
        break;
      case 'nonWorkable':
        filteredData = allData.filter(a => 
          a.allocatedUser && a.allocatedUser.toLowerCase().includes(currentUserName.toLowerCase()) && 
          a.statusCode === 'Non-Workable'
        );
        break;
      default:
        filteredData = allData;
    }

    const headers = ['Client', 'Visit ID', 'Patient Name', 'DOS', 'Billed Amount', 'Balance Amount', 'Type', 'Claim Type', 'Status Code', 'Action Code', 'Allocated User'];
    const csvData = [headers];

    filteredData.forEach(account => {
      csvData.push([
        account.client,
        account.visitId,
        account.patientName,
        account.dos,
        account.billedAmount,
        account.balanceAmount,
        account.type,
        account.claimType,
        account.statusCode,
        account.actionCode,
        account.allocatedUser
      ]);
    });

    return csvData;
  } catch (error) {
    throw new Error('Error exporting data: ' + error.message);
  }
}

// ============================================
// UTILITY FUNCTIONS
// ============================================

function formatDate(date) {
  if (!date) return '';
  if (typeof date === 'string') return date;

  try {
    const d = new Date(date);
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const year = d.getFullYear();
    return `${month}/${day}/${year}`;
  } catch (error) {
    return '';
  }
}

function getCurrentUser() {
  return {
    email: Session.getActiveUser().getEmail(),
    name: getCurrentUserDisplayName()
  };
}

function getCurrentUserDisplayName() {
  try {
    const sheet = SpreadsheetApp.openById(CONFIG.AR_OUTSTANDING.sheetId)
      .getSheetByName(CONFIG.AR_OUTSTANDING.sheets.dropdown.name);

    const data = sheet.getDataRange().getValues();
    const currentEmail = Session.getActiveUser().getEmail();

    // Look in Users column (G) for matching entry
    for (let i = 1; i < data.length; i++) {
      const userEntry = String(data[i][6]).trim();
      if (userEntry && userEntry.toLowerCase().includes(currentEmail.split('@')[0].toLowerCase())) {
        return userEntry;
      }
    }

    // Fallback: capitalize username
    const username = currentEmail.split('@')[0];
    return username.charAt(0).toUpperCase() + username.slice(1);
  } catch (error) {
    Logger.log('Could not fetch display name: ' + error.message);
    const username = Session.getActiveUser().getEmail().split('@')[0];
    return username.charAt(0).toUpperCase() + username.slice(1);
  }
}

// ============================================
// DIAGNOSTIC FUNCTIONS
// ============================================

function testTrackerLogAccess() {
  try {
    Logger.log('=== TRACKER LOG TEST ===');
    Logger.log('Sheet ID: ' + CONFIG.LAH_CONSOLIDATED.sheetId);
    Logger.log('Sheet Name: ' + CONFIG.LAH_CONSOLIDATED.sheetName);
    Logger.log('Enabled: ' + CONFIG.LAH_CONSOLIDATED.enabled);

    const ss = SpreadsheetApp.openById(CONFIG.LAH_CONSOLIDATED.sheetId);
    Logger.log('✅ Spreadsheet: ' + ss.getName());

    const sheet = ss.getSheetByName(CONFIG.LAH_CONSOLIDATED.sheetName);
    if (!sheet) {
      Logger.log('❌ Sheet not found');
      Logger.log('Available: ' + ss.getSheets().map(s => s.getName()).join(', '));
      return { success: false, error: 'Sheet not found' };
    }

    Logger.log('✅ Sheet found: ' + sheet.getName());
    Logger.log('✅ Rows: ' + sheet.getLastRow());

    if (sheet.getLastRow() > 1) {
      const sample = sheet.getRange(2, 1, 1, 9).getValues()[0];
      Logger.log('Sample Visit ID: ' + sample[1]);
    }

    return { success: true };
  } catch (error) {
    Logger.log('❌ ERROR: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}
